// Reward and chest illustrations as 64×64 SVG, which NSImage renders natively.
import AppKit
import SwiftUI

struct ArtImage: View {
    let name: String
    var size: CGFloat = 64
    var locked = false

    var body: some View {
        Group {
            if let img = Art.image(name) { Image(nsImage: img).resizable().interpolation(.high) }
            else { Image(systemName: "gift.fill").resizable().scaledToFit().foregroundStyle(.warning) }
        }
        .frame(width: size, height: size)
        .grayscale(locked ? 1 : 0)
        .opacity(locked ? 0.45 : 1)
        .accessibilityHidden(true)
    }
}

@MainActor
enum Art {
    private static var cache: [String: NSImage] = [:]

    static func image(_ name: String) -> NSImage? {
        if let hit = cache[name] { return hit }
        guard let svg = svgs[name], let img = NSImage(data: Data(svg.utf8)) else { return nil }
        cache[name] = img
        return img
    }

