/// Trophy medal: ribbon tails, a metal rim and face, and the badge's symbol engraved in it.
struct Medal: View {
    enum Metal {
        case bronze, silver, gold, jade, locked
        // rim light, rim dark, face light, face dark, ribbon
        var colors: [Color] {
            switch self {
            case .bronze: [0xf0b98a, 0x7a3f1c, 0xc98652, 0x6b3818, 0x8a4b2a].map { Color(hex: $0) }
            case .silver: [0xf6f8fa, 0x7b858c, 0xd3d9dd, 0x6d767d, 0x5b6a74].map { Color(hex: $0) }
            case .gold: [0xffe7a3, 0x9a5f10, 0xf5c451, 0xa86c14, 0xb0741a].map { Color(hex: $0) }
            case .jade: [0xa6f5e7, 0x15685c, 0x4fcab8, 0x17695d, 0x1f7a6d].map { Color(hex: $0) }
            case .locked: [0x3b4449, 0x1a1f22, 0x293034, 0x181d20, 0x22292d].map { Color(hex: $0) }
            }
        }
    }

    let icon: String
    let metal: Metal
    var size: CGFloat = 64

    var body: some View {
        let c = metal.colors, s = size / 96, locked = metal == .locked
        ZStack {
            Ribbon().fill(c[4]).overlay(Ribbon().fill(.black.opacity(0.18)))
            Circle().fill(LinearGradient(colors: [c[0], c[1]], startPoint: .topLeading, endPoint: .bottomTrailing))
                .frame(width: 60 * s, height: 60 * s).offset(y: -4 * s)
            Circle().strokeBorder(.black.opacity(0.25), style: StrokeStyle(lineWidth: max(0.6, s), dash: [1.2 * s, 2.6 * s]))
                .frame(width: 54 * s, height: 54 * s).offset(y: -4 * s)
            Circle().fill(LinearGradient(colors: [c[2], c[3]], startPoint: UnitPoint(x: 0.2, y: 0), endPoint: UnitPoint(x: 0.8, y: 1)))
                .overlay(Circle().strokeBorder(.black.opacity(0.28), lineWidth: 1.5 * s))
                .overlay(alignment: .top) {
                    Ellipse().fill(LinearGradient(colors: [.white.opacity(0.35), .white.opacity(0)], startPoint: .top, endPoint: .center))
                        .frame(width: 40 * s, height: 22 * s).offset(y: 1 * s)
                }
                .frame(width: 48 * s, height: 48 * s).offset(y: -4 * s)
            ZStack {
                Image(systemName: icon).foregroundStyle(.white.opacity(locked ? 0.06 : 0.4)).offset(y: 1.2 * s)
                Image(systemName: icon).foregroundStyle(locked ? Color(hex: 0x0d1114) : .black.opacity(0.58))
            }
            .font(.system(size: 25 * s, weight: .heavy))
            .offset(y: -4 * s)
        }
        .frame(width: size, height: size)
        .shadow(color: .black.opacity(locked ? 0 : 0.45), radius: 7 * s, y: 5 * s)
        .accessibilityHidden(true)
    }
}

/// The two ribbon tails under a medal, on a 96×96 grid.
private struct Ribbon: Shape {
    func path(in r: CGRect) -> Path {
        let s = r.width / 96
        var p = Path()
        let tails: [[(CGFloat, CGFloat)]] = [[(36, 62), (30, 88), (37.5, 83), (42, 90), (46, 66)], [(60, 62), (66, 88), (58.5, 83), (54, 90), (50, 66)]]
        for pts in tails {
            p.addLines(pts.map { CGPoint(x: r.minX + $0.0 * s, y: r.minY + $0.1 * s) })
            p.closeSubpath()
        }
        return p
    }
}
